import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DCKC-kU_.js";const m=JSON.parse('{"title":"0007 — Current Forms exclude substrate operation","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0007-current-forms-exclude-substrate-operation.md","filePath":"spec/decisions/0007-current-forms-exclude-substrate-operation.md"}'),i={name:"spec/decisions/0007-current-forms-exclude-substrate-operation.md"};function n(s,e,c,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_0007-—-current-forms-exclude-substrate-operation" tabindex="-1">0007 — Current Forms exclude substrate operation <a class="header-anchor" href="#_0007-—-current-forms-exclude-substrate-operation" aria-label="Permalink to &quot;0007 — Current Forms exclude substrate operation&quot;">​</a></h1><ul><li>Status: accepted</li><li>Date: 2026-08-05</li><li>Owners: Takoform maintainers</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The first v1alpha2 candidate generator copied each retained v1alpha1 Definition and fixture tree, then changed its API version, Form version, status, and description. This mechanically carried fields such as concurrency, replicas, CPU, memory, size class, high availability, routing, health checks, storage class, consumer retry policy, and provider compatibility into the reset line.</p><p>Several current concepts resemble Cloudflare products because Takosumi Cloud is the first real workload and host. That resemblance is not itself a defect: edge execution, key/value storage, queues, schedules, and addressable stateful entities are useful general abstractions. The defect is allowing one substrate&#39;s operating model to determine the portable desired schema.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The normative ownership boundary is <a href="./../portability-boundary.html"><code>../portability-boundary.md</code></a>.</p><p>Current Forms own independently implementable workload semantics only. Host support profiles own capability availability. Adapters own compatibility with external protocols or ecosystems. Operators own placement, routing, scaling, health, capacity, and retry policy. Service Offerings own quota, availability, price, and support.</p><p>Cloudflare-like general resource concepts are allowed. Cloudflare-specific product identity, configuration, compatibility surfaces, account topology, limits, and commercial behavior are not portable fields.</p><p>The current catalog is independently authored. Candidate generation may reuse the shared schema type system, but may not read or copy a Legacy Definition or fixture tree. Exact current field sets and forbidden substrate/operation fields are executable tests.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>EdgeWorker</code> retains artifact, entrypoint, runtime capability, configuration, connections, and an HTTP Interface; assets policy, request timeout, and concurrency move out of the Form.</li><li><code>ContainerService</code> retains an immutable image, configuration, connections, and an HTTP Interface; ports, public routing, health probes, CPU, memory, and replicas move out of the Form.</li><li><code>RelationalDatabase</code> retains engine/schema semantics; storage size, size class, and high availability move out of the Form.</li><li><code>ObjectBucket</code> retains object lifecycle semantics; storage class and access protocol compatibility move to host/adapter layers.</li><li><code>Queue</code> retains delivery order and message-retention semantics; consumer batching, retry, visibility, delay, and capacity limits move out of the Form.</li><li><code>StatefulEntity</code> uses a generic artifact entrypoint and persistence capability; provider-shaped class and migration controls do not enter the Form.</li><li>Takosumi Cloud can continue to implement these Forms with Cloudflare or another substrate without making that substrate part of Takoform.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Rename every Cloudflare-like concept.</strong> Rejected because neutral semantics, not unfamiliar names, provide portability.</li><li><strong>Keep all fields as open capability tokens.</strong> Rejected because an open token can still smuggle placement, pricing, or one provider&#39;s control plane into the portable contract.</li><li><strong>Standardize compatibility APIs in each Form.</strong> Rejected because protocol compatibility is adapter/Interface material and varies independently from Resource lifecycle.</li><li><strong>Filter Legacy fields only at documentation time.</strong> Rejected because the provider schema, fixtures, digests, and host contract would remain coupled to the old substrate-shaped source.</li></ul>',14)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
